function validate([dimensions]) {
  if (!Array.isArray(dimensions) || dimensions.length < 1 || dimensions.length > 100) return 'dimensions needs 1 to 100 rectangles.';
  for (const pair of dimensions) {
    if (!Array.isArray(pair) || pair.length !== 2) return 'Each rectangle is [length, width].';
    if (pair.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each side is a whole number from 1 to 100.';
  }
  return null;
}

