function areaOfMaxDiagonal(dimensions) {
  let bestDiagonal = 0;
  let bestArea = 0;

  for (const [length, width] of dimensions) {
    const diagonal = length * length + width * width;
    const area = length * width;
    if (diagonal > bestDiagonal) {
      bestDiagonal = diagonal;
      bestArea = area;
    } else if (diagonal === bestDiagonal && area > bestArea) {
      bestArea = area;
    }
  }
  return bestArea;
}

