function areaOfMaxDiagonal(dimensions) {
  // Sort by squared diagonal, then area, both descending; the first rectangle wins.
  const ranked = dimensions.map(([l, w]) => ({ d: l * l + w * w, a: l * w }));
  ranked.sort((p, q) => q.d - p.d || q.a - p.a);
  return ranked[0].a;
}

