function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 100 : 1 + Math.floor(rand() * 6);
  const top = large ? 100 : 1 + Math.floor(rand() * 12);
  // Rectangles with equal diagonals but different areas make the tie-break matter.
  const ties = [[3, 4], [6, 8], [5, 5], [1, 7], [10, 10], [2, 14], [25, 60], [39, 52], [16, 63], [33, 56]];
  const dimensions = [];
  for (let i = 0; i < n; i++) {
    if (rand() < 0.3) {
      const pick = ties[Math.floor(rand() * ties.length)];
      dimensions.push(rand() < 0.5 ? [pick[0], pick[1]] : [pick[1], pick[0]]);
    } else {
      dimensions.push([1 + Math.floor(rand() * top), 1 + Math.floor(rand() * top)]);
    }
  }
  return [dimensions];
}
